import re

frames = []
with open('/tmp/ocr_final.txt') as f:
    data = f.read()
for part in data.split('===FRAME '):
    if not part.strip():
        continue
    lines = part.split('\n')
    frames.append(lines[1:])

moves = []
prev_count = None
for fl in frames:
    text = ' '.join(fl)
    m = re.search(r'Moves:\s*(\d+)', text)
    if m:
        cnt = int(m.group(1))
        if prev_count is None or cnt > prev_count:
            prev_count = cnt
        else:
            continue
    line = None
    for l in fl:
        if l.startswith('>'):
            line = l
    if line is None:
        continue
    cmd = line[1:].strip()
    if not cmd or '===FRAME' in cmd:
        continue
    cmd = cmd.split()[0] if ' ' in cmd and re.match(r'^[a-z]+ [a-z]+$', cmd) is None else cmd
    if prev_count is not None and cnt == prev_count:
        continue
    moves.append((prev_count, cmd))

# keep only the cmd at the moment of a count change
seen = {}
for cnt, cmd in moves:
    seen[cnt] = cmd

with open('/app/solution.txt','w') as out:
    for cnt in sorted(seen):
        out.write(seen[cnt] + '\n')
